./novamind-operation python-c "
import novamind_api as nm

# Step 6: Set targeted ad spend
# Focus on high-TAM individuals first (S1, S2, S3) and enterprises (E1, E2, E3)
# We don't know which channels work best yet, so diversify

print('=== Setting Targeted Ad Spend ===')
result = nm.marketing.set_targeted_ad_spend(targeted_spend={
    'social_media': {
        'S1': 100,
        'S2': 80,
        'S3': 60,
    },
    'search_ads': {
        'S1': 80,
        'S2': 100,
        'S3': 80,
    },
    'linkedin': {
        'E1': 50,
        'E2': 60,
        'E3': 40,
    },
    'content_marketing': {
        'S2': 50,
        'S3': 40,
    },
})
print(f\"Total daily ad spend: \${result['total_per_day']:.0f}\")

# Step 7: Set lead promotion (first billing discount)
print('\\n=== Setting Lead Promotion ===')
result = nm.marketing.set_lead_promotion(
    global_promotion=5.0,
    by_group={
        'S2': 10.0,
        'S3': 10.0,
        'E2': 15.0,
    }
)
print(result)

# Step 8: Set ongoing promotion
print('\\n=== Setting Ongoing Promotion ===')
result = nm.pricing.set_promotion(
    global_promotion=0.0,  # No ongoing discount globally
    by_group={
        'S1': 1.0,  # \$1 for price-sensitive to help retention
    }
)
print(result)

print('\\n=== Setup Complete ===')
print('Initial cash: \$1,000,000')
print('Daily burn: operations (\$300) + dev (\$500) + capacity (\$215) + ad spend (\$930) + lead cost = ~\$2,000/day before revenue')
"

