arguments.command:
./novamind-operation python-c "
import novamind_api as nm

# Get recent ledger entries
result = nm.query('SELECT day, category, amount FROM ledger WHERE day >= 56 ORDER BY day DESC LIMIT 100')
print('=== Recent Ledger Entries (Day 56+) ===')
by_day = {}
for row in result['rows']:
    day = row['day']
    if day not in by_day:
        by_day[day] = {}
    cat = row['category']
    if cat not in by_day[day]:
        by_day[day][cat] = 0
    by_day[day][cat] += row['amount']

for day in sorted(by_day.keys(), reverse=True)[:7]:
    print(f\"Day {day}:\")
    for cat in sorted(by_day[day].keys()):
        amt = by_day[day][cat]
        if abs(amt) > 10:  # Only show significant amounts
            print(f\"  {cat:30s}: {amt:10.2f}\")
"

